<div class="form-grid"><x-field name="name" label="Library name" :value="$edit['name'] ?? ''" required /><label class="field"><span>Media type</span><select name="mediaType"><option value="book" @selected(($edit['mediaType'] ?? '') === 'book')>Audiobooks & ebooks</option><option value="podcast" @selected(($edit['mediaType'] ?? '') === 'podcast')>Podcasts & video</option></select></label></div><x-field name="paths" label="Library folders (one absolute path per line)" type="textarea" rows="4" :value="collect($edit['folders'] ?? [])->pluck('fullPath')->join(chr(10))" required hint="Use paths inside the server container, such as /audiobooks or /podcasts." /><details class="advanced-options" @if($errors->any()) open @endif><summary>Metadata & scan settings</summary><div class="stack"><div class="form-grid"><x-field name="provider" label="Metadata provider" list="metadata-providers" :value="$edit['provider'] ?? ''" hint="For example google, audible, itunes, or a custom provider slug." /><x-field name="icon" label="Library icon" list="library-icons" :value="$edit['icon'] ?? 'database'" /></div><div class="form-grid"><x-field name="scanSchedule" label="Automatic scan schedule" :value="$edit['settings']['autoScanCronExpression'] ?? ''" hint="Leave blank to disable. For example: 0 3 * * * scans daily at 03:00." /><x-field name="markAsFinishedPercentComplete" label="Mark finished at (%)" type="number" :value="$edit['settings']['markAsFinishedPercentComplete'] ?? ''" min="0" max="100" /><x-field name="markAsFinishedTimeRemaining" label="Mark finished with seconds remaining" type="number" :value="$edit['settings']['markAsFinishedTimeRemaining'] ?? ''" min="0" /></div><label class="check"><input type="checkbox" name="disableWatcher" value="1" @checked($edit['settings']['disableWatcher'] ?? false)>Disable file watching for this library</label><label class="check"><input type="checkbox" name="disableAutoScan" value="1" @checked($edit['settings']['disableAutoScan'] ?? false)>Disable scheduled scans</label>
</div></details>
<datalist id="metadata-providers"><option value="google">Google Books</option><option value="audible">Audible</option><option value="itunes">Apple</option></datalist><datalist id="library-icons"><option value="database">Library</option><option value="audiobookshelf">Audiobookshelf</option><option value="books">Books</option><option value="podcast">Podcast</option></datalist>
